  /* generated by _parts/ks_data.py from content/insights/drafts + cms/seed/_draft-topics.json. Do not edit by hand. */
  var KS = {"cats":[{"key":"who","code":"WHO","name":"Who I build for","blurb":"The people and teams the work is for."},{"key":"what","code":"WHAT","name":"What I build","blurb":"The things that end up on the site."},{"key":"how","code":"HOW","name":"How it gets built","blurb":"The steps and habits behind every build."},{"key":"watch","code":"WATCH","name":"What I watch for","blurb":"The problems I check for before anything ships."},{"key":"ideas","code":"IDEAS","name":"Why before how","blurb":"Ideas from philosophy and science that shape the work."},{"key":"known","code":"KNOWN","name":"Known for","blurb":"The signature pieces people ask about."}],"topics":[{"slug":"creative-studios","name":"Creative studios","category":"who","definition":"Studios whose work is visual and physical, where the site has to show scale and craft rather than describe it.","services":["webflow-development","webgl-data","motion"],"missions":["510-visuals"],"faq":[]},{"slug":"service-businesses","name":"Service businesses","category":"who","definition":"Firms that sell expertise, like law, finance or consulting, where trust and clear answers do the selling.","services":["webflow-development","cms-integrations","performance"],"missions":["knowledge-system"],"faq":[]},{"slug":"mission-led-teams","name":"Mission-led teams","category":"who","definition":"Nonprofits and companies doing good, who need a site that explains the mission and is easy for a small team to keep up.","services":["webflow-development","branding"],"missions":[],"faq":[]},{"slug":"agencies-partners","name":"Agencies + partners","category":"who","definition":"Studios and agencies that bring me in for the interactive, 3D or CMS-heavy part of a bigger project.","services":["webgl-data","motion","cms-integrations"],"missions":[],"faq":[]},{"slug":"webflow-cms","name":"Webflow CMS","category":"what","definition":"Collections, fields and templates shaped around how a team publishes, so pages build themselves from content.","services":["webflow-development","cms-integrations"],"missions":["510-visuals","knowledge-system"],"faq":["cms-integrations-2","cms-integrations-3","webflow-development-1"]},{"slug":"interactive-3d","name":"Interactive 3D","category":"what","definition":"Globes, maps and scenes visitors can turn, zoom and use to decide, fed by the CMS instead of hard-coded.","services":["webgl-data","performance"],"missions":["510-visuals"],"faq":["webgl-data-1","webgl-data-2","webgl-data-3"]},{"slug":"motion-scroll","name":"Motion + scroll","category":"what","definition":"Scroll systems, reveals and drag physics built with GSAP and Lenis, with easing tuned by hand.","services":["motion"],"missions":["510-visuals","ab-identity"],"faq":["motion-2"]},{"slug":"brand-identity","name":"Brand identity","category":"what","definition":"A mark, color and type built on a grid, so the brand holds up from a favicon to a billboard.","services":["branding"],"missions":["ab-identity"],"faq":["branding-1","branding-2","branding-3"]},{"slug":"design-systems","name":"Design systems","category":"what","definition":"Variables, components and type scales defined once, so page ten is as sharp as page one.","services":["design-systems","webflow-development"],"missions":["ab-identity","510-visuals"],"faq":["design-systems-1","design-systems-2","design-systems-3"]},{"slug":"discovery","name":"Discovery","category":"how","definition":"The first conversation: goals, audience and what a win looks like, before anyone opens Figma.","services":["webflow-development","branding"],"missions":[],"faq":["home-4"]},{"slug":"prototyping","name":"Prototyping","category":"how","definition":"The key pieces built as a clickable prototype and reviewed together before the real build starts.","services":["webflow-development","webgl-data","motion"],"missions":["510-visuals","ab-identity"],"faq":[]},{"slug":"custom-code","name":"Custom code","category":"how","definition":"Plain JavaScript for what Webflow can't do natively, kept in a repo instead of pasted into settings.","services":["webflow-development","custom-deploys"],"missions":["510-visuals"],"faq":["home-1","custom-deploys-1"]},{"slug":"versioned-deploys","name":"Versioned deploys","category":"how","definition":"Every release tagged in GitHub and loaded from jsDelivr with an integrity hash, so any change can be rolled back.","services":["custom-deploys","webflow-development"],"missions":["510-visuals"],"faq":["custom-deploys-3"]},{"slug":"handoff","name":"Handoff","category":"how","definition":"A walkthrough and a written guide, so the team owns the site, the files and the code after launch.","services":["webflow-development","design-systems"],"missions":["510-visuals","ab-identity"],"faq":["home-2","custom-deploys-2"]},{"slug":"mobile-performance","name":"Mobile performance","category":"watch","definition":"Heavy visuals that still load fast on a phone: lazy loading, paused loops and a Lighthouse pass on every page.","services":["performance","webgl-data"],"missions":["510-visuals"],"faq":["home-3","motion-1","performance-1","performance-2","performance-3"]},{"slug":"tap-vs-hover","name":"Tap vs hover","category":"watch","definition":"A tap fires hover events too. Interactive pieces have to tell a finger from a mouse or they break on phones.","services":["motion","webflow-development"],"missions":[],"faq":[]},{"slug":"reduced-motion","name":"Reduced motion","category":"watch","definition":"Respecting the system setting that asks for less movement, without turning the site into a static page.","services":["motion"],"missions":["510-visuals","ab-identity"],"faq":["motion-3"]},{"slug":"crawlable-links","name":"Crawlable links","category":"watch","definition":"Every page you want found needs a real link in the HTML. Script-only navigation is invisible to search and AI tools.","services":["webflow-development","performance"],"missions":[],"faq":[]},{"slug":"scope-creep","name":"Scope creep","category":"watch","definition":"The slow drift of a project past its goal. Named early, it becomes a decision instead of a surprise.","services":["webflow-development"],"missions":[],"faq":[]},{"slug":"perceived-speed","name":"Perceived speed","category":"watch","definition":"How fast a site feels, which is not always how fast it is. Loading states and motion change the clock in your head.","services":["performance","motion"],"missions":[],"faq":[]},{"slug":"philosophy-at-work","name":"Philosophy at work","category":"ideas","definition":"Old questions about purpose and meaning, used as working tools for building websites.","services":[],"missions":[],"faq":[]},{"slug":"science-of-time","name":"Science of time","category":"ideas","definition":"Physics and psychology of time, and what they say about waiting on a screen.","services":[],"missions":[],"faq":[]},{"slug":"better-questions","name":"Asking better questions","category":"ideas","definition":"The habit of asking why before how, so the brief describes the problem and not just the wish list.","services":["webflow-development"],"missions":[],"faq":[]},{"slug":"saying-no","name":"Saying no","category":"ideas","definition":"Turning down a good idea so the great one ships. The kindest thing a project can hear, early.","services":[],"missions":[],"faq":[]},{"slug":"search-ai-answers","name":"Search + AI answers","category":"known","definition":"Structured data, clear answers and connected pages, so search engines and AI assistants can tell what a site knows.","services":["cms-integrations","webflow-development"],"missions":["knowledge-system"],"faq":[]},{"slug":"knowledge-system","name":"Knowledge System","category":"known","definition":"A connected content system: a shared vocabulary, a library of answers and pages that link themselves when you tag an entry.","services":["cms-integrations","webflow-development","design-systems"],"missions":["knowledge-system"],"faq":[]},{"slug":"micro-interaction","name":"Micro-interaction","category":"known","definition":"The small responses to a cursor, a tap or a scroll that make a site feel made by a person.","services":["motion"],"missions":["510-visuals","ab-identity"],"faq":[]}],"insights":[{"n":"01","slug":"structured-data-webflow-cms","title":"How to add structured data to Webflow CMS pages (no plugin)","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"Webflow can write JSON-LD for every CMS item from the fields you already have. Where to paste it, how to insert the fields, and the one character that breaks it.","answer":"Paste a JSON-LD <code>&lt;script&gt;<\/code> block into the CMS template's <strong>Page settings › Custom code › Before <code>&lt;/head&gt;<\/code><\/strong>, and insert the item's fields with <strong>+ Add field<\/strong> wherever a value belongs. Every item then ships its own structured data, built from the same fields as the page. Keep straight double quotes (<code>\"<\/code>) out of those fields, because one of them breaks the whole block.","topics":["search-ai-answers","webflow-cms","knowledge-system"],"services":["cms-integrations","webflow-development"],"missions":["knowledge-system"],"mins":3,"words":549,"body":[{"t":"h2","x":"Why bother","id":"why-bother"},{"t":"p","x":"Structured data is a small, machine-readable description of what a page is: this is a service, this is a project, this person made it. Search engines use it to understand a page, and AI assistants lean on the same signals when they decide what a site is about. On a static page you write it once. On a CMS template, you want it to write itself for every item."},{"t":"h2","x":"The two places JSON-LD can live in Webflow","id":"the-two-places-json-ld-can-live-in-webflow"},{"t":"ol","items":["<strong>Static pages:<\/strong> Page settings › Custom code, or through the API. You write the values in by hand.","<strong>CMS template pages:<\/strong> the template's own Custom code field. This is the one that matters, because it can read the item's fields."]},{"t":"p","x":"What doesn't work: page-level schema set through the API can't see CMS fields. If your schema needs the item's name, it has to live in the template."},{"t":"h2","x":"Step by step","id":"step-by-step"},{"t":"ol","items":["Open the collection template (for example <strong>Services Template<\/strong>) and go to <strong>Page settings<\/strong>.","In <strong>Custom code › Before <code>&lt;/head&gt;<\/code><\/strong>, paste a skeleton like this:"]},{"t":"code","lang":"html","code":"<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Service\",\n  \"@id\": \"https://yoursite.com/services/[Slug]#service\",\n  \"url\": \"https://yoursite.com/services/[Slug]\",\n  \"name\": \"[Name]\",\n  \"description\": \"[Summary]\",\n  \"provider\": { \"@id\": \"https://yoursite.com/#person\" }\n}\n<\/script>"},{"t":"ol","items":["Delete each <code>[Field]<\/code> marker and put the cursor there, then use <strong>+ Add field<\/strong> to insert the real field. Webflow shows it as a purple token.","Publish, open an item, view source, and paste the page into Google's Rich Results Test or the Schema.org validator."]},{"t":"h2","x":"The gotchas I actually hit","id":"the-gotchas-i-actually-hit"},{"t":"ul","items":["<strong>Quotes break everything.<\/strong> Webflow inserts field values as plain text. If a summary contains <code>\"like this\"<\/code>, the JSON ends early and the whole block is ignored, silently. Use curly quotes in copy, or keep a separate plain field for schema. I put the rule right in the field's help text so whoever edits the CMS sees it.","<strong>Empty images.<\/strong> If an image field is empty, you get <code>\"image\": \"\"<\/code>. Validators warn on that. Either make the field required or keep a fallback image.","<strong>Stable <code>@id<\/code>s.<\/strong> Give every entity an absolute <code>@id<\/code> (<code>https://yoursite.com/#person<\/code>) and point other pages at it instead of repeating the details. That's how separate pages add up to one clear picture of who you are.","<strong>Only describe what's on the page.<\/strong> FAQ schema for questions that aren't visible, or a rating nobody gave you, is a spam signal. If the page doesn't show it, the markup shouldn't claim it."]},{"t":"h2","x":"Where this fits","id":"where-this-fits"},{"t":"p","x":"On its own, schema is a label. Connected to a shared vocabulary (the topics a site is known for) it becomes part of a system: the same fields drive the page, the related links and the structured data, so nothing drifts. That's the idea behind the <a href=\"mission-debrief.html#knowledge-system\">Knowledge System<\/a>."}],"notes":["Every step and gotcha comes from this site's own SEO pass (Services + Missions templates). Nothing invented.","Uses <code>yoursite.com<\/code>, not your domain, on purpose."],"no":"BN-01"},{"n":"02","slug":"crawlable-collection-links-webflow","title":"Your Webflow project pages might be invisible to Google. Check your links.","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"If a script builds your card links, crawlers may never find the pages behind them. A two-minute check, and the Designer setting that fixes it.","answer":"If JavaScript adds your cards' links, the HTML Google downloads may not link to your project pages at all. View the page source (not the inspector) and search for <code>/work/<\/code> or your collection's path. If nothing comes up, set each card's link to <strong>Current [Collection] page<\/strong> in the Designer so the link exists before any script runs.","topics":["crawlable-links","webflow-cms","custom-code"],"services":["webflow-development","performance"],"missions":["knowledge-system"],"mins":3,"words":458,"body":[{"t":"h2","x":"How I found it on my own site","id":"how-i-found-it-on-my-own-site"},{"t":"p","x":"During the SEO pass on this portfolio I downloaded every page the way a crawler sees it and listed the links. The home page linked to every service. The Work page linked to every service. Neither linked to a single mission debrief."},{"t":"p","x":"The cards worked perfectly for people. The script that animates them also sets their <code>href<\/code>, so in a browser everything clicked through. But the raw HTML had placeholder links, and the four real case studies were orphans: nothing a crawler reads pointed to them."},{"t":"h2","x":"Why it happens","id":"why-it-happens"},{"t":"p","x":"It's a natural side effect of interactive builds. You hand a card to a script for a warp transition, a hover effect or a filter, and at some point the script becomes the thing that knows where the card goes. Google does run JavaScript, but later and less reliably than it reads HTML, and plenty of other crawlers and AI tools don't run it at all. Links that exist only after a script runs are links you're hoping for, not links you have."},{"t":"h2","x":"The two-minute check","id":"the-two-minute-check"},{"t":"ol","items":["Open the page, then <strong>View page source<\/strong> (Ctrl+U / Cmd+Option+U). The inspector shows the page after scripts ran, so it will lie to you here.","Search the source for your collection path (<code>/work/<\/code>, <code>/projects/<\/code>, <code>/blog/<\/code>).","Every item you want found should appear as a real <code>href<\/code>."]},{"t":"p","x":"If you'd rather check a whole site: fetch each page with <code>curl<\/code>, pull out every <code>href<\/code>, and list which collection items nobody links to."},{"t":"h2","x":"The fix in Webflow","id":"the-fix-in-webflow"},{"t":"ul","items":["Select the card's <strong>Link Block<\/strong> inside the Collection List.","Link settings › <strong>Current [Collection] page<\/strong> (for a reference field, the referenced item's page).","Keep your script, but let it <em>read<\/em> the <code>href<\/code> instead of writing it. Enhance the link; don't be the link."]},{"t":"p","x":"For \"next project\" cards, bind the link to the reference field (for example <em>Next mission<\/em>) so each page links forward in plain HTML."},{"t":"h2","x":"A related trap: hidden and placeholder items","id":"a-related-trap-hidden-and-placeholder-items"},{"t":"p","x":"While you're in there, look at what <em>is<\/em> linked. A hidden client or a placeholder project still has a live page if its item is published. Give the template a <code>noindex<\/code> switch (a plain text field inserted into a robots meta tag works well) and keep those items out of the sitemap until they're real."}],"notes":["True story from this build (the Designer fix is still on your list).","The line about AI tools not running JavaScript is a general statement; fine to keep or soften."],"no":"BN-02"},{"n":"03","slug":"lenis-gsap-webflow-smooth-scroll","title":"Smooth scroll without the stutter: Lenis + GSAP in Webflow","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"Smooth scroll that stutters usually has two clocks fighting. Drive Lenis from GSAP's ticker, load its stylesheet, and pause what's off screen.","answer":"Most Lenis + GSAP stutter in Webflow comes from three things: two animation clocks running at once, Lenis's stylesheet missing, and canvas animations that never pause. Drive Lenis from <code>gsap.ticker<\/code>, add Lenis's CSS, and stop anything that isn't on screen.","topics":["motion-scroll","mobile-performance","custom-code"],"services":["motion","performance"],"missions":["510-visuals"],"mins":2,"words":332,"body":[{"t":"h2","x":"1. One clock, not two","id":"1-one-clock-not-two"},{"t":"p","x":"Lenis ships with its own <code>requestAnimationFrame<\/code> loop. GSAP has another. Run both and the scroll position and your ScrollTriggers update on slightly different beats, which reads as a tiny, maddening judder."},{"t":"code","lang":"js","code":"var lenis = new Lenis({ autoRaf: false });\nlenis.on('scroll', ScrollTrigger.update);\ngsap.ticker.add(function (time) { lenis.raf(time * 1000); });\ngsap.ticker.lagSmoothing(0);"},{"t":"p","x":"Now there's one heartbeat: GSAP ticks, Lenis moves, ScrollTrigger reads the new position in the same frame."},{"t":"h2","x":"2. Load the Lenis stylesheet","id":"2-load-the-lenis-stylesheet"},{"t":"p","x":"Lenis relies on a few CSS rules (on <code>html.lenis<\/code>, <code>.lenis-smooth<\/code> and friends). Without them, the browser's own smooth scrolling and scroll anchoring fight Lenis. It's one <code>&lt;link&gt;<\/code> in your site head and easy to forget."},{"t":"h2","x":"3. Pause what nobody can see","id":"3-pause-what-nobody-can-see"},{"t":"p","x":"A WebGL scene or a canvas starfield that keeps drawing while it's off screen steals frame time from the scroll. Pause it:"},{"t":"code","lang":"js","code":"new IntersectionObserver(function (entries) {\n  entries[0].isIntersecting ? scene.play() : scene.pause();\n}).observe(document.querySelector('.scene'));"},{"t":"p","x":"Same for hidden tabs: stop the loop when <code>document.hidden<\/code> is true."},{"t":"h2","x":"Two smaller ones","id":"two-smaller-ones"},{"t":"ul","items":["<strong>Panels that grow on click.<\/strong> If a section expands under the reader, the browser's scroll anchoring can jump the page by hundreds of pixels. Give that area <code>overflow-anchor: none<\/code>.","<strong>Nested scroll areas.<\/strong> A scrollable list inside a Lenis page won't scroll with the wheel until you add <code>data-lenis-prevent<\/code> to it."]},{"t":"h2","x":"How to know it's fixed","id":"how-to-know-it-s-fixed"},{"t":"p","x":"Record the page with the Performance panel open while you scroll. You want one steady rhythm of frames, not two interleaved ones, and no long tasks landing mid-scroll. Then try it on a mid-range phone, because that's where your visitors actually are."}],"notes":["These are the fixes from your own site's scroll work (the \"smoothness trio\").","The Lenis option name <code>autoRaf<\/code> matches recent Lenis versions; double-check against the version you load before publishing."],"no":"BN-03"},{"n":"04","slug":"interactive-3d-webflow-performance","title":"Interactive 3D in Webflow that doesn't wreck your mobile score","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"A 3D scene can sit on a Webflow page without slowing the first screen. Load it late, pause it off screen, draw fewer pixels on phones, and always have a still fallback.","answer":"Heavy 3D doesn't have to mean a slow page. Load the scene only when it's about to be seen, pause it whenever it's off screen, render at a lower pixel ratio on touch devices, and give reduced-motion visitors a still image. The first screen stays fast because the 3D isn't on the critical path at all.","topics":["interactive-3d","mobile-performance","custom-code"],"services":["webgl-data","performance"],"missions":["510-visuals"],"mins":2,"words":380,"body":[{"t":"h2","x":"Why 3D is worth it","id":"why-3d-is-worth-it"},{"t":"p","x":"A globe of installations, a product you can turn, a map of case results: interactive 3D can show in two seconds what a paragraph fails to say. The goal isn't spectacle. It's giving visitors something they can use to decide."},{"t":"h2","x":"Rule 1: don't load it until it matters","id":"rule-1-don-t-load-it-until-it-matters"},{"t":"code","lang":"js","code":"var io = new IntersectionObserver(function (entries) {\n  if (!entries[0].isIntersecting) return;\n  io.disconnect();\n  loadScene(); // import Three.js, build the scene\n}, { rootMargin: '400px' });\nio.observe(document.querySelector('[data-scene]'));"},{"t":"p","x":"The library, the models and the textures all wait. Until then, a lightweight poster image holds the space so nothing jumps when the scene arrives."},{"t":"h2","x":"Rule 2: pause it when nobody's looking","id":"rule-2-pause-it-when-nobody-s-looking"},{"t":"p","x":"A render loop that keeps running below the fold burns battery and steals frames from scrolling. Keep the same observer and pause and resume. Stop it on hidden tabs too."},{"t":"h2","x":"Rule 3: draw fewer pixels on phones","id":"rule-3-draw-fewer-pixels-on-phones"},{"t":"p","x":"Phones have very dense screens. Rendering at their full pixel ratio multiplies the work for detail nobody can see at arm's length."},{"t":"code","lang":"js","code":"renderer.setPixelRatio(matchMedia('(pointer: coarse)').matches ? 1 : Math.min(devicePixelRatio, 2));"},{"t":"h2","x":"Rule 4: a fallback that still tells the story","id":"rule-4-a-fallback-that-still-tells-the-story"},{"t":"p","x":"For visitors with <strong>reduced motion<\/strong> turned on, and for older devices, show a still frame of the scene with the same information. The point of the 3D is the information; the motion is a bonus."},{"t":"h2","x":"Rule 5: measure on a real phone","id":"rule-5-measure-on-a-real-phone"},{"t":"p","x":"Lighthouse on a desktop tells you very little. Test on a mid-range phone over a normal connection, and look at when the first screen appears and whether scrolling stays smooth once the scene is running."},{"t":"h2","x":"What to put in the CMS","id":"what-to-put-in-the-cms"},{"t":"p","x":"Keep the data (locations, products, results) in Webflow collections and let the scene read it from <code>data-<\/code> attributes on hidden list items. Your team adds an item, publishes, and the 3D updates itself, no developer needed."}],"notes":["Matches what the 510 Visuals globe and this site's planets do. No performance numbers claimed.","Positioning follows your direction: interactive 3D that's useful to clients and visitors, not \"globes\"."],"no":"BN-04"},{"n":"05","slug":"tap-is-not-hover-touch-bugs","title":"Tap is not hover: the touch bug hiding in interactive Webflow builds","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"On phones, one tap fires enter, leave and click in a row. If your hover code toggles state, it can undo the tap before your click handler sees it.","answer":"On a touchscreen, a single tap fires <code>pointerenter<\/code>, <code>pointerleave<\/code> and then <code>click<\/code>, one after another. If hover code opens something on enter and closes it on leave, it closes it again before your click handler runs. Ignore touch in the hover handlers (<code>if (e.pointerType === 'touch') return;<\/code>) and let taps use <code>click<\/code> alone.","topics":["tap-vs-hover","micro-interaction","mobile-performance"],"services":["motion","webflow-development"],"missions":[],"mins":2,"words":352,"body":[{"t":"h2","x":"The bug","id":"the-bug"},{"t":"p","x":"On my About page there's an Interstellar card. On desktop, you hover it and a little ring ship flies close to a black hole. Up close, tapping the black hole fast fires the ship's thrusters. On phones, tapping did... nothing. The card flew close, but the thrusters never fired."},{"t":"h2","x":"What was actually happening","id":"what-was-actually-happening"},{"t":"p","x":"Here's the order of events for one tap:"},{"t":"ol","items":["<code>pointerenter<\/code> → my hover code added <code>is-close<\/code>.","<code>pointerleave<\/code> → my hover code removed <code>is-close<\/code>.","<code>click<\/code> on the black hole → \"is the ship close?\" No. Ignore the tap.","<code>click<\/code> bubbles to the card → the tap toggle sets <code>is-close<\/code> again."]},{"t":"p","x":"So the ship <em>looked<\/em> close, but every thruster tap was checked in the split second when it wasn't. Two handlers, each correct on its own, cancelling each other out."},{"t":"h2","x":"The fix","id":"the-fix"},{"t":"code","lang":"js","code":"card.addEventListener('pointerenter', function (e) {\n  if (e.pointerType === 'touch') return; // taps use click\n  card.classList.add('is-close');\n});\ncard.addEventListener('pointerleave', function (e) {\n  if (e.pointerType === 'touch') return;\n  card.classList.remove('is-close');\n});"},{"t":"p","x":"Mouse and pen still get hover. Touch gets one clear path: tap to open, tap to close."},{"t":"h2","x":"How to catch these before a client does","id":"how-to-catch-these-before-a-client-does"},{"t":"ul","items":["<strong>Log the event order<\/strong> once on a real phone. You'll be surprised what a tap sends.","<strong>Don't trust desktop emulation alone.<\/strong> Device mode fakes the screen size, but its clicks still arrive as mouse clicks.","<strong>Test with synthetic events<\/strong> when you can't hold the device: dispatch <code>PointerEvent<\/code>s with <code>pointerType: 'touch'<\/code> in the order a real tap uses, then assert the state."]},{"t":"h2","x":"The general lesson","id":"the-general-lesson"},{"t":"p","x":"Hover is a mouse idea. On touch there's no \"hovering\", only a tap that briefly pretends. Any interaction that means something on hover needs a separate, deliberate answer for touch."}],"notes":["This is the v0.23.5 fix from this session, told plainly. You may want to link the About page card once the article is live."],"no":"BN-05"},{"n":"06","slug":"webflow-custom-code-github-jsdelivr","title":"Versioned custom code for Webflow: GitHub, jsDelivr and SRI","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"Keep Webflow custom code in GitHub, serve each release from jsDelivr pinned to a tag, and lock it with a subresource integrity hash. Rollbacks become one line.","answer":"Write your custom code in a GitHub repo, tag every release (<code>v1.4.0<\/code>), and load it in Webflow from jsDelivr pinned to that tag with an <code>integrity<\/code> hash. Every deploy is a new URL, so there's no cache to fight, a bad release rolls back by changing one version number, and the browser refuses a file that doesn't match its hash.","topics":["versioned-deploys","custom-code","handoff"],"services":["webflow-development","custom-deploys"],"missions":["510-visuals"],"mins":2,"words":385,"body":[{"t":"h2","x":"The problem with pasting code into Webflow","id":"the-problem-with-pasting-code-into-webflow"},{"t":"p","x":"Webflow's custom code fields are fine for a few lines. Past that, code pasted into a settings box has no history, no review and no way back. The next developer finds 30 KB of mystery JavaScript and no idea which part is safe to touch."},{"t":"h2","x":"The setup","id":"the-setup"},{"t":"ol","items":["<strong>A repo<\/strong> with <code>src/<\/code> (readable modules) and <code>dist/<\/code> (built files).","<strong>A build step<\/strong> that bundles, minifies and writes a hash for each file.","<strong>A tag per deploy:<\/strong> <code>git tag -a v1.4.0 &amp;&amp; git push --tags<\/code>.","<strong>Load it from jsDelivr, pinned to the tag:<\/strong>"]},{"t":"code","lang":"html","code":"<script src=\"https://cdn.jsdelivr.net/gh/you/site@v1.4.0/dist/site.prod.js\"\n        integrity=\"sha384-...\" crossorigin=\"anonymous\"><\/script>"},{"t":"h2","x":"Why pin a tag and not <code>@main<\/code>","id":"why-pin-a-tag-and-not-main"},{"t":"p","x":"<code>@main<\/code> is cached and changes under you. A tag never changes, so the URL <em>is<\/em> the version. Want the previous release back? Change <code>v1.4.0<\/code> to <code>v1.3.2<\/code>. That's the whole rollback."},{"t":"h2","x":"What the integrity hash buys you","id":"what-the-integrity-hash-buys-you"},{"t":"p","x":"The <code>integrity<\/code> attribute tells the browser what the file must hash to. If the CDN ever serves something different, it won't run. It also catches your own mistakes: if the hash doesn't match, you deployed a different file than you built."},{"t":"h2","x":"Two gotchas from real deploys","id":"two-gotchas-from-real-deploys"},{"t":"ul","items":["<strong>Don't name files <code>*.min.js<\/code>.<\/strong> jsDelivr can serve its own minified copy of a <code>.min.js<\/code> path, which won't match your hash. Name builds <code>*.prod.js<\/code>.","<strong>Verify before you switch.<\/strong> A brand-new tag can take a minute to appear on the CDN. Fetch the file, hash it, compare with your build's hash, and only then update Webflow."]},{"t":"h2","x":"The handoff payoff","id":"the-handoff-payoff"},{"t":"p","x":"The client's team sees a short, readable list of scripts with version numbers. A developer who inherits the site gets a repo with a changelog. Nobody has to be afraid of the custom code tab."}],"notes":["This is exactly how this site and 5 TEN ship code. Swap \"you/site\" for a real example repo if you'd like to link yours (it's public)."],"no":"BN-06"},{"n":"07","slug":"reduced-motion-without-losing-the-magic","title":"Reduced motion without losing the magic","theme":"build-notes","themeName":"Build notes","code":"BN","status":"approved","desc":"Some visitors ask their device for less motion. Honoring that doesn't mean a blank, lifeless site. Keep the information, calm the movement, and offer a still version of every moment.","answer":"When a visitor's device asks for reduced motion, keep everything the motion was <em>saying<\/em> and drop only the movement. Check <code>prefers-reduced-motion<\/code> in every animation, replace big moves with a fade or a still end state, and design the still version on purpose rather than just switching things off.","topics":["reduced-motion","motion-scroll","micro-interaction"],"services":["motion"],"missions":[],"mins":2,"words":319,"body":[{"t":"h2","x":"Who this is for","id":"who-this-is-for"},{"t":"p","x":"Motion can make people feel sick: vestibular disorders, migraines, or just a long day. Phones and computers let people ask for less of it, and a site can read that preference. It's a small check, and it matters to the people who turned it on."},{"t":"h2","x":"Check it everywhere, once","id":"check-it-everywhere-once"},{"t":"code","lang":"js","code":"var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\nif (!reduce) {\n  gsap.from('.fade-up', { y: 40, opacity: 0, stagger: 0.08 });\n}"},{"t":"p","x":"In CSS, the same idea:"},{"t":"code","lang":"css","code":"@media (prefers-reduced-motion: reduce) {\n  .spin, .float, .marquee { animation: none; }\n}"},{"t":"p","x":"Put the check in one shared place so every new animation gets it for free."},{"t":"h2","x":"Keep the meaning, not the movement","id":"keep-the-meaning-not-the-movement"},{"t":"p","x":"Ask what each animation is <em>for<\/em>:"},{"t":"ul","items":["A counter ticking up shows a number → show the final number.","A scroll-scrubbed timeline shows progress → show the finished timeline.","A warp transition says \"you're going somewhere\" → a quick fade says it too.","A game or a cutscene → skip to the result and let people read it at their own pace."]},{"t":"h2","x":"Design the still version","id":"design-the-still-version"},{"t":"p","x":"The lazy version of reduced motion is a site where things are simply missing. The better version is a set of good still frames: the end state of each scene, composed like a poster. If you designed the animation, you already know which frame tells the story."},{"t":"h2","x":"Test it in thirty seconds","id":"test-it-in-thirty-seconds"},{"t":"ul","items":["<strong>macOS:<\/strong> Settings › Accessibility › Display › Reduce motion.","<strong>Windows:<\/strong> Settings › Accessibility › Visual effects › Animation effects off.","<strong>Chrome DevTools:<\/strong> Rendering › Emulate <code>prefers-reduced-motion<\/code>."]},{"t":"p","x":"Then scroll the whole site and ask: did I lose any information? If not, you've done it right."}],"notes":["Mirrors the rule already in your code standards (a reduced-motion check in every animation) and how the boss fight handles it."],"no":"BN-07"},{"n":"08","slug":"why-before-how-philosophy-web-design","title":"Why before how: what a philosophy degree taught me about building websites","theme":"why-before-how","themeName":"Why before how","code":"WB","status":"approved","desc":"Philosophy trains you to ask what something is for before arguing about how to do it. It turns out that's also the best way to start a website.","answer":"The most useful thing philosophy taught me isn't any single idea. It's the habit of asking what something is <em>for<\/em> before deciding how to build it. In web projects, that one question saves more time than any tool: it turns \"we need a new website\" into a clear goal, a shorter sitemap and a design that has a reason for every section.","topics":["philosophy-at-work","better-questions","discovery"],"services":["webflow-development","branding"],"missions":[],"mins":5,"words":992,"body":[{"t":"h2","x":"The question behind the question","id":"the-question-behind-the-question"},{"t":"p","x":"Philosophy is mostly the practice of not accepting the first answer. Someone says \"justice\", and Socrates asks what they mean, then asks again, until the real idea is on the table. It can be annoying at dinner. It's wonderful in a discovery call."},{"t":"p","x":"When a client says \"we need a new website\", the honest follow-up is: <em>why now, and what should be different after?<\/em> Sometimes the answer is \"we look outdated\". More often it's \"nobody understands what we actually do\", or \"our team can't update anything\", or \"we're invisible to the people we want to reach\". Those are three completely different projects, and they deserve three completely different sites."},{"t":"p","x":"Socrates liked to say he knew nothing, and then asked questions until everyone else noticed they didn't either. That sounds like a trick, but it's the most generous thing you can do at the start of a project: admit you don't know yet what the site is for, and find out together."},{"t":"h2","x":"Aristotle's four causes, applied to a homepage","id":"aristotle-s-four-causes-applied-to-a-homepage"},{"t":"p","x":"Aristotle said that to really understand a thing, you need four answers about it. He called them causes, but \"reasons\" is closer to what he meant:"},{"t":"ol","items":["<strong>The material cause:<\/strong> what it's made of. For a website, that's the content: the words, the photos, the projects, the data in the CMS.","<strong>The formal cause:<\/strong> the shape it takes. The structure, the layout, the design system.","<strong>The efficient cause:<\/strong> what brings it into being. The build: the person, the tools, Webflow, the code.","<strong>The final cause:<\/strong> what it's <em>for<\/em>. Aristotle called this the <em>telos<\/em>, the end the thing aims at."]},{"t":"p","x":"Most website projects start with the efficient cause (\"which platform?\") or the formal cause (\"can it look like this site I saw?\"). Aristotle would start with the final cause, because it explains the other three. Once you know a homepage exists to help a nervous first-time client understand what you do in ten seconds, the right material, form and build mostly choose themselves."},{"t":"p","x":"The acorn is his favorite example: its whole shape makes sense once you know it's trying to become an oak. A website is the same. The layout only makes sense once you know what it's trying to become."},{"t":"h2","x":"Form follows function (and function follows purpose)","id":"form-follows-function-and-function-follows-purpose"},{"t":"p","x":"Designers have their own version of this. The architect Louis Sullivan wrote in 1896 that \"form ever follows function\", and the shortened phrase became a slogan for a century of modern design. It's usually read as \"make it useful, not decorative\". I read it one step further back: function follows <em>purpose<\/em>. A button's function is to be clicked. Its purpose is whatever the visitor is trying to get done by clicking it."},{"t":"p","x":"That's why I don't treat interactive 3D, motion or a clever CMS as features to add. Each one has to answer a why. A globe earns its place when it helps a visitor see where a studio has worked in one second instead of reading a list. A scroll animation earns its place when it explains a sequence better than a paragraph would. If the only answer to \"why is this here?\" is \"because it's impressive\", it goes."},{"t":"h2","x":"How it shows up in my process","id":"how-it-shows-up-in-my-process"},{"t":"ul","items":["<strong>Discovery starts with purpose, not pages.<\/strong> Before a sitemap, we agree on what a visitor should understand, feel and do.","<strong>Every section earns its place.<\/strong> If I can't say what a section is for, it doesn't get designed.","<strong>Features answer a why.<\/strong> Interactive 3D, motion, a CMS: each one has to make something clearer or easier, not just more impressive.","<strong>The purpose gets written down.<\/strong> One sentence at the top of the brief, so later decisions have something to be checked against."]},{"t":"p","x":"A few of the questions I actually ask on a first call, all of them versions of Socrates' \"what do you mean by that?\":"},{"t":"ul","items":["What should someone believe about you after thirty seconds on the site that they don't believe now?","Who is the visitor you'd most hate to lose, and what do they need to see first?","What does your team dread updating today?","If the new site worked perfectly, what would you notice a month later?"]},{"t":"h2","x":"Clear definitions make better sites","id":"clear-definitions-make-better-sites"},{"t":"p","x":"A lot of philosophy is defining terms carefully so an argument doesn't slide around. Websites have the same problem. If \"services\", \"solutions\" and \"what we do\" mean slightly different things on different pages, visitors get lost, and so do search engines and AI assistants. Naming things once and using the names consistently is half of good structure."},{"t":"p","x":"It's the idea behind the shared vocabulary on this site: every topic in the Observatory is defined once, in a sentence, and every article, mission and service points to the same words. It's a small, very old philosophical habit turned into a CMS collection."},{"t":"h2","x":"Why, then how","id":"why-then-how"},{"t":"p","x":"None of this means endless talk. Asking why is fast when you do it early and expensive when you do it late. A week of honest questions at the start is cheaper than a redesign six months after launch because nobody asked what the site was for."},{"t":"p","x":"The how still matters, a lot. I care about easing curves and clean class names more than is probably healthy. But the how is only good relative to a why. Get the why right, and the how becomes a craft problem instead of an argument."}],"notes":[],"no":"WB-01"},{"n":"09","slug":"interstellar-time-dilation-perceived-performance","title":"One hour there, seven years here: Interstellar and why waiting feels longer than it is","theme":"why-before-how","themeName":"Why before how","code":"WB","status":"approved","desc":"In Interstellar, time runs slow near a black hole because gravity bends it. On the web, time bends too, in the visitor's head. What physics, philosophy and psychology each say about a loading screen.","answer":"In <em>Interstellar<\/em>, an hour on Miller's planet costs seven years back home, because a huge mass nearby really does slow time down relative to a distant observer. On the web, time bends in a different way: a wait with nothing to look at <em>feels<\/em> longer than the same wait with visible progress. You can't change physics, but you can change how a wait is experienced, by showing something useful immediately and making progress visible.","topics":["science-of-time","perceived-speed","motion-scroll"],"services":["performance","motion"],"missions":[],"mins":5,"words":873,"body":[{"t":"h2","x":"The physics, briefly","id":"the-physics-briefly"},{"t":"p","x":"Einstein's general relativity says gravity isn't only a force; it's the shape of spacetime. Close to a very massive object, clocks tick more slowly compared with clocks far away. This isn't a trick of perception. GPS satellites have to correct for it (along with the effect of their speed) or their positions would drift."},{"t":"p","x":"The film pushes the idea to an extreme: Miller's planet orbits very close to a supermassive black hole, so close that the crew's hour on the surface costs them years relative to Earth. The physicist Kip Thorne advised the production so the science would hold up, and the black hole itself, Gargantua, was rendered from equations he worked out with the visual effects team."},{"t":"p","x":"The detail I love is that nobody on Miller's planet <em>feels<\/em> slow. Their watches tick normally. Their hour is a real hour. Time dilation only shows up when two clocks are compared. Which is exactly the situation of a website and its visitor."},{"t":"h2","x":"Two clocks: the one on the wall and the one in your head","id":"two-clocks-the-one-on-the-wall-and-the-one-in-your-head"},{"t":"p","x":"Philosophers noticed long before Einstein that time isn't one simple thing. Saint Augustine wrote in his <em>Confessions<\/em> that he knew perfectly well what time was, until someone asked him to explain it. His best answer was that we measure time in the mind: the past as memory, the future as expectation, the present as attention."},{"t":"p","x":"Much later, the French philosopher Henri Bergson drew a line between clock time, which is measured and divided into equal pieces, and <em>durée<\/em>, lived duration, which stretches and shrinks with what we're experiencing. Ten minutes in a dentist's chair and ten minutes with a friend are the same on the clock and nothing alike in <em>durée<\/em>."},{"t":"p","x":"A loading screen lives in Bergson's second kind of time. Your analytics measure the clock. Your visitor lives the duration."},{"t":"h2","x":"The other kind of slow time","id":"the-other-kind-of-slow-time"},{"t":"p","x":"Visitors don't carry atomic clocks. They carry attention. And attention stretches time when there's nothing to hold it: a blank white screen for a couple of seconds feels far longer than the same seconds spent watching content arrive."},{"t":"p","x":"Psychologists have studied this in a very un-cinematic place: lines. In a well-known 1985 paper, <em>The Psychology of Waiting Lines<\/em>, David Maister set out a few principles that anyone who has queued will recognize:"},{"t":"ul","items":["<strong>Occupied time feels shorter than unoccupied time.<\/strong>","<strong>Uncertain waits feel longer than known, finite waits.<\/strong>","<strong>Unexplained waits feel longer than explained waits.<\/strong>","<strong>Waits before a process starts feel longer than waits once it's underway.<\/strong>"]},{"t":"p","x":"Every one of those maps onto a page load. A blank screen is unoccupied, uncertain, unexplained and hasn't visibly started. It's the worst possible way to spend two seconds."},{"t":"h2","x":"What that means on a website","id":"what-that-means-on-a-website"},{"t":"p","x":"That's why good loading design isn't only about making things faster (though do that too). It's about what the visitor experiences while they wait."},{"t":"ul","items":["<strong>Show something real, right away.<\/strong> Text and layout first, heavy media after. A page that's readable in a second feels fast even if a 3D scene is still loading below.","<strong>Make progress visible.<\/strong> A skeleton of the layout, a progress bar that actually moves, a counter. Uncertainty is what makes waiting hurt.","<strong>Start the process on screen.<\/strong> Once something is visibly happening, the wait is \"underway\", and it feels shorter.","<strong>Keep movement honest.<\/strong> A spinner that loops forever tells people nothing. A step that fills tells them the wait will end.","<strong>Don't hide the wait behind decoration.<\/strong> A long intro animation feels like the site is wasting your time, because it is."]},{"t":"h2","x":"Designing with the second clock","id":"designing-with-the-second-clock"},{"t":"p","x":"On this site, moving between pages is a short warp: the stars stretch, then the next page arrives. It isn't there to delay you. It gives the eye something to follow during the moment the next page is loading anyway, so the wait is occupied instead of blank. When a visitor has asked for reduced motion, the warp becomes a simple fade, because an occupied wait should never cost someone their comfort."},{"t":"p","x":"The same idea runs through every heavy piece I build. A 3D globe loads only when it's about to come into view, and there's always something readable above it. The expensive thing arrives while you're already busy with the useful thing."},{"t":"h2","x":"The point","id":"the-point"},{"t":"p","x":"In the film, time dilation is the price of getting close to something enormous. On the web, there's no reason to pay it. Measure the clock on the wall, but design for the clock in the visitor's head: get people to the good part first, and let the heavy, beautiful things arrive while they're already reading."}],"notes":[],"no":"WB-02"},{"n":"10","slug":"nietzsche-three-metamorphoses-scope-creep","title":"The camel, the lion and the child: Nietzsche on scope creep","theme":"why-before-how","themeName":"Why before how","code":"WB","status":"approved","desc":"Zarathustra's three metamorphoses (carry, refuse, create) map surprisingly well onto a web project. Especially the part where somebody has to say no.","answer":"In <em>Thus Spoke Zarathustra<\/em>, Nietzsche describes the spirit changing three times: into a camel that carries every burden, a lion that says \"no\" to the rules it was handed, and a child that creates something new. A good project goes through the same three stages. First you take everything in, then you refuse what doesn't serve the goal, and only then do you build. Skip the lion and you get scope creep.","topics":["philosophy-at-work","scope-creep","saying-no"],"services":["webflow-development"],"missions":[],"mins":5,"words":922,"body":[{"t":"h2","x":"The three metamorphoses","id":"the-three-metamorphoses"},{"t":"p","x":"Early in the book, Zarathustra tells a short parable. The spirit becomes a <strong>camel<\/strong>, kneeling to be loaded with the heaviest things it can bear. Then, alone in the desert, it becomes a <strong>lion<\/strong>, which fights a great dragon named \"Thou shalt\" and wins the right to say a sacred \"No\". Finally it becomes a <strong>child<\/strong>: innocence, a new beginning, \"a sacred Yes\"."},{"t":"p","x":"It's about how people grow, not about websites. Nietzsche was writing about morality, about the values we inherit and the courage it takes to make our own. But it's hard to read it on a deadline and not recognize the shape of a project."},{"t":"h2","x":"The camel: carry it all (at first)","id":"the-camel-carry-it-all-at-first"},{"t":"p","x":"Discovery is camel work. You take in every goal, every stakeholder's wish, every \"wouldn't it be nice if\". That's good. You can't design for needs you haven't heard, and the camel's strength is real: patience, listening, carrying things that aren't yours yet."},{"t":"p","x":"The mistake is staying a camel. A project that keeps kneeling for one more load (one more page, one more feature, one more integration) never gets across the desert. Camels are admirable, and they are very slow."},{"t":"h2","x":"The dragon called \"Thou shalt\"","id":"the-dragon-called-thou-shalt"},{"t":"p","x":"In the parable, the dragon's scales are covered in golden commandments, every value that has ever been handed down, each one saying \"Thou shalt\". The lion can't create anything new while it's still obeying them."},{"t":"p","x":"Web projects have their own dragon. Its scales say things like:"},{"t":"ul","items":["Thou shalt have a carousel on the homepage.","Thou shalt have a page for every service, even the one nobody buys.","Thou shalt match what the competitor did.","Thou shalt add it, because someone important mentioned it once."]},{"t":"p","x":"None of these are evil. Some are even right, for some projects. The problem is that they arrive as rules instead of reasons. The lion's job isn't to reject everything. It's to ask each golden scale \"why?\" and keep only the ones that have an answer."},{"t":"h2","x":"The lion: the sacred no","id":"the-lion-the-sacred-no"},{"t":"p","x":"This is the stage most projects skip, and it's the one that matters. The lion looks at everything the camel carried and asks which of it actually serves the goal we agreed on. Then it says no to the rest, out loud."},{"t":"p","x":"Scope creep isn't a villain. It's the natural result of never having a lion. Every request sounds reasonable on its own; only a clear purpose (\"why before how\") lets you say no without it feeling arbitrary. The \"no\" usually isn't forever, either. Often it's \"not in this launch\"."},{"t":"p","x":"What the lion actually sounds like, on a real project:"},{"t":"ul","items":["\"That's a great idea. It doesn't serve the goal we wrote down, so it goes on the later list.\"","\"We can do that, and here's what it pushes out of this launch. Which one matters more?\"","\"Let's launch without it and see if anyone asks for it.\""]},{"t":"p","x":"The lion isn't rude. It's clear. And clarity turns out to be kind: nobody on a project enjoys a scope that keeps growing, least of all the person paying for it."},{"t":"h2","x":"Designers already know this","id":"designers-already-know-this"},{"t":"p","x":"Design has its own lions. Dieter Rams, who shaped Braun's products for decades, summed up his principles in three words: <em>weniger, aber besser<\/em>, \"less, but better\". Antoine de Saint-Exupéry, a pilot before he was a writer, put it as the idea that perfection arrives not when there's nothing left to add, but when there's nothing left to take away."},{"t":"p","x":"Both are lion sentences. They're not against richness; this site has a playable boss fight on the About page, so I'm clearly not a minimalist. They're against things that are there only because nobody said no. Every element that stays should be a choice, not a leftover."},{"t":"h2","x":"The child: build something new","id":"the-child-build-something-new"},{"t":"p","x":"Only after the no can you really create. The child isn't carrying anyone's leftover burdens. Nietzsche calls it \"a wheel rolling out of itself\", a first movement, play. With a smaller, clearer scope, the design gets bolder, the build gets cleaner, and the launch actually happens."},{"t":"p","x":"I think this is why prototyping feels like play when the scope is right. You're not negotiating anymore; you're making. The best ideas on a project usually show up in this stage, because there's finally room for them."},{"t":"h2","x":"In practice","id":"in-practice"},{"t":"ul","items":["Write down the goal in one sentence before collecting features.","Put every request on one list, then sort it against that sentence.","Ask each \"thou shalt\" for its reason. Keep the ones that have one.","Say the \"no\" early, and kindly, with a \"later\" list so nothing is lost.","Protect the build phase from new cargo. New ideas go to the next launch."]},{"t":"p","x":"Carry, refuse, create. In that order, and not twice in the same week."},{"t":"p","x":"(If you've found the boss fight on my About page, you already know what the final boss is called.)"}],"notes":[],"no":"WB-03"}],"faq":{"cms-integrations-2":["What about CMS limits?","I plan around Webflow item and reference limits from day one, so you do not hit a wall later."],"cms-integrations-3":["Does it update automatically?","Yes, on a schedule or on change, depending on the source."],"webflow-development-1":["Can my team really edit it?","Yes. Text, images and CMS items are all editable in the Webflow Editor, and the handoff guide shows exactly where everything lives."],"webgl-data-1":["Can I add points myself?","Yes. Points come from CMS items, so adding a project or result is the same as adding any other item."],"webgl-data-2":["Will it work on phones?","Yes. Touch gestures are tuned separately, and lower-power devices get a lighter version."],"webgl-data-3":["Is it locked to Webflow?","No. The code is plain JavaScript on GitHub, so it can move with you."],"motion-2":["Can you add motion to an existing Webflow site?","Yes, as long as the structure is clean. I review the build first and flag anything that needs tidying."],"branding-1":["Can you design the website too?","Yes. Brand and website together is the best way to make both feel like one thing."],"branding-2":["How many concepts do I see?","Usually two or three distinct directions before we pick one to refine."],"branding-3":["Do I own the files?","Yes. You get every source and export file at the end."],"design-systems-1":["Do I need a design system?","If your site has more than a handful of pages or more than one person editing it, it pays for itself quickly."],"design-systems-2":["Can you systematize an existing site?","Yes. We audit it first, then move it onto tokens step by step."],"design-systems-3":["Figma or Webflow first?","Figma, then mirrored in Webflow with matching names."],"home-4":["How long does a project take?","It depends on scope. A marketing site with one custom interactive centerpiece usually runs [X–Y weeks] from brief to launch."],"home-1":["Do you only build in Webflow?","Webflow is home base, because clients can edit it after launch. The custom pieces (3D scenes, maps, scroll systems) are plain JavaScript hosted on GitHub, so they aren't locked to one platform."],"custom-deploys-1":["When should I skip Webflow?","When you need logins, heavy data, custom backends or things the Editor cannot model. For most marketing sites, Webflow is still the better choice."],"custom-deploys-3":["Who maintains it?","You can, another developer can, or I can on a retainer."],"home-2":["Can my team edit the site after launch?","Yes. Content lives in the CMS and the build follows Client-First naming. Animations read from CMS fields and stable classes, so editing content won't break them. You get a handoff guide and a walkthrough video."],"custom-deploys-2":["Can non-developers edit it?","Yes, with a headless CMS set up for your team."],"home-3":["Will all this motion slow the site down?","Heavy pieces load only when they scroll into view and pause when they leave. Every interaction has a reduced-motion fallback, and each page gets a Lighthouse pass before launch."],"motion-1":["Will it slow the site down?","No. Animations use transforms, pause off-screen and are tested on mid-range phones."],"performance-1":["Can you speed up a site you did not build?","Yes. Most gains come from images, scripts and loading order, which can be fixed without a rebuild."],"performance-2":["What score will I get?","It depends on the site. The goal is a fast first screen and smooth scrolling on real phones, not a vanity number."],"performance-3":["Will I lose the animations?","No. They stay, they just load smarter."],"motion-3":["What about accessibility?","Every effect respects the reduced-motion setting and never hides content behind an animation."]},"svcPlanet":{"webflow-development":{"type":"gas","colors":"#0d2a66,#146EF5,#8fb8ff,#e8f0ff,#1d2350","glow":"rgba(20,110,245,.4)"},"webgl-data":{"type":"ice","colors":"#0f1a1d,#1c2227,#37535a,#5a8a94,#b8c9cc","glow":"rgba(94,234,212,.4)"},"motion":{"type":"gas","colors":"#0a3d22,#0AE448,#9dffc2,#e9fff1,#073d20","glow":"rgba(10,228,72,.35)"},"branding":{"type":"gas","colors":"#3b1f12,#a44a1f,#ff8a4c,#ffd29a,#6b2b16","glow":"rgba(255,106,61,.4)"},"custom-deploys":{"type":"rocky","colors":"#1b1b1f,#3a3a44,#8a8fa3,#e9eaf0","glow":"rgba(242,240,234,.25)"},"cms-integrations":{"type":"ice","colors":"#1d2350,#3f4fa8,#8fb1ff,#e9d9ff","glow":"rgba(143,177,255,.4)"},"design-systems":{"type":"terra","colors":"#2b1f5c,#7c5cff,#b8a6ff,#e9d9ff,#1d2350","glow":"rgba(124,92,255,.4)"},"performance":{"type":"rocky","colors":"#3b1f12,#a44a1f,#ff8a4c,#ffd29a","glow":"rgba(255,209,102,.35)"}}};
